-- Phase 2: Blueprint Service Independent Database Schema\n-- Database: postgres-blueprint:5438\n\nCREATE TABLE IF NOT EXISTS blueprints (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_id UUID NOT NULL,\n    name VARCHAR(255),\n    content JSONB,\n    status VARCHAR(20),\n    created_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS blueprint_versions (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    blueprint_id UUID NOT NULL REFERENCES blueprints(id) ON DELETE CASCADE,\n    version INT,\n    content JSONB,\n    created_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX idx_blueprints_user_id ON blueprints(user_id);\nCREATE INDEX idx_blueprint_versions_blueprint_id ON blueprint_versions(blueprint_id);\n\nGRANT USAGE ON SCHEMA public TO blueprint_user;\nGRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO blueprint_user;\nGRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO blueprint_user;\n"